namespace sv_d725173ea4464747bc7e89919bccf64e.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// All interactive components in the same circuit share this instance.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private Theme _currentTheme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// All subscribing components should call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose()
    {
        // Clear all subscribers to prevent leaks
        OnChange = null;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeService.AccentColor;">
    @GetThemeIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeService.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var theme in Enum.GetValues<Theme>())
        {
            var isActive = ThemeService.CurrentTheme == theme;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.CurrentTheme = theme">
                @theme
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <input type="color" class="form-control form-control-color mb-3"
           value="@ThemeService.AccentColor"
           @onchange="HandleColorChange" />

    <p class="text-muted">
        Current: <strong>@ThemeService.CurrentTheme</strong> /
        <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleColorChange(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

